public Detector getDetector() {
    // be as lazy as possible and cache
    Detector localDetector = context.get(Detector.class);
    if (localDetector != null) {
        return localDetector;
    }
    if (detector != null) {
        return detector;
    }
    detector = new DefaultDetector(getMimeTypes());
    return detector;
}
